&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc211334544&quot;&gt;&lt;/a&gt;&lt;a name=&quot;_Toc211406302&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;FİLO VE MİLLETVEKİLLERİMİZE TEŞEKK&amp;Uuml;R&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;S&amp;ouml;zlerimin hemen başında ge&amp;ccedil;en hafta Akdeniz&amp;rsquo;de Gazze&amp;rsquo;ye doğru yol alan, &amp;Ouml;zg&amp;uuml;rl&amp;uuml;k Filosundaki &amp;ccedil;abalarıyla, sadece bu milletin değil, vicdan sahibi t&amp;uuml;m milletlerin vekili olan Sema Silkin &amp;Uuml;n&amp;rsquo;e, Mehmet Atmaca&amp;rsquo;ya ve Necmettin &amp;Ccedil;alışkan&amp;rsquo;a hoş geldiniz diyorum.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Onların şahsında Filoyu organize eden, filoya her t&amp;uuml;rl&amp;uuml; katkı sağlayan t&amp;uuml;m vicdan sahiplerine bir kez daha teşekk&amp;uuml;r ediyorum. Allah sizlerden razı olsun.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc211334545&quot;&gt;&lt;/a&gt;&lt;a name=&quot;_Toc211406303&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;YARA BANDI SİYASETİ&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Değerli arkadaşlar;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;T&amp;uuml;m eşitsizliklere rağmen Gazze tam iki yıl direndi ve diz &amp;ccedil;&amp;ouml;kmedi. Filistinli direniş&amp;ccedil;iler, ilk g&amp;uuml;nden itibaren b&amp;ouml;lge &amp;uuml;lkelerinden beklediği &amp;ldquo;insani ve siyasi desteği&amp;rdquo; maalesef g&amp;ouml;remedi. Filistinli direniş&amp;ccedil;iler; her platformda; İsrail&amp;#39;in işgalci olduğunun vurgulanmasını istedi.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;İşgalci İsrail&amp;rsquo;e karşı tam boykot, tam tecrit, tam ambargo ve kesintisiz yaptırım uygulanmasını istedi.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Ancak T&amp;uuml;rkiye başta olmak &amp;uuml;zere b&amp;ouml;lge &amp;uuml;lkeleri, Filistin&amp;#39;e; yiyecek, giyecek, sargı bezi ve yara bandı g&amp;ouml;ndermenin &amp;ouml;tesine ge&amp;ccedil;emediler. Bunlar da maalesef işgalci İsrail&amp;#39;in m&amp;uuml;saade ettiği kadarıyla yapılabildi.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bunun adı onurlu bir direnişe destek vermek değildir. Bunun adı;&amp;nbsp;katliama ara verildiğinde olay mahalline &amp;ldquo;yara bandı&amp;rdquo; g&amp;ouml;t&amp;uuml;rmektir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/h1&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc211334546&quot;&gt;&lt;/a&gt;&lt;a name=&quot;_Toc211406304&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;ATEŞKES BARIŞ DEĞİLDİR!&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;İşte b&amp;ouml;yle ge&amp;ccedil;en iki yılın ardından, yine bir &amp;ldquo;ateşkes&amp;rdquo; g&amp;uuml;ndemiyle &amp;ldquo;yeni bir başlangı&amp;ccedil;&amp;rdquo; vaadiyle karşı karşıyayız.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Değerli arkadaşlar;&amp;nbsp;&lt;em&gt;&amp;ldquo;Ateşkes, barış değildir.&amp;rdquo;&lt;/em&gt;&amp;nbsp;&amp;ldquo;Ateşkes&amp;rdquo;, işgalin ve zulm&amp;uuml;n bittiği anlamına gelmez. Hepimiz biliyoruz ki; Gazze Şeridi&amp;rsquo;ne &amp;ccedil;izilen &amp;ccedil;izgiyi, mavi &amp;ccedil;izgiden sarı &amp;ccedil;izgiye; sarı &amp;ccedil;izgiden kırmızı &amp;ccedil;izgiye &amp;ccedil;ekmekle işgal son bulmayacaktır.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Yine hepimiz biliyoruz ki; bug&amp;uuml;n tampon b&amp;ouml;lge dedikleri yerlere b&amp;ouml;lge &amp;uuml;lkelerinin asker yerleştirmesiyle &amp;ldquo;işgal&amp;rdquo; sona ermeyecektir. İsrail, bulunduğu her santimetrekare toprakta işgalcidir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc211334547&quot;&gt;&lt;/a&gt;&lt;a name=&quot;_Toc211406305&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;MESELE NETANYAHU DEĞİLDİR!&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Mesele sadece Netanyahu meselesi değildir!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Netanyahu, 3 farklı d&amp;ouml;nemde; toplamda 18 yıldır işgalci İsrail&amp;rsquo;in başbakanı. Ancak Filistin topraklarında, İsrail işgali 77 yıldır devam ediyor. İşgal, katliam, soykırım ve savaş su&amp;ccedil;larının faturasını sadece Netanyahu&amp;rsquo;ya kesip, işgalci İsrail&amp;rsquo;i g&amp;ouml;rmezden gelmek tam da Siyonizm&amp;rsquo;in istediği şeydir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;İsrail, en başından beri &amp;ccedil;ocuk katilidir. İsrail, en başından beri soykırımcıdır. İsrail b&amp;ouml;lgede barışa ve huzura y&amp;ouml;nelik en b&amp;uuml;y&amp;uuml;k tehdittir. Ve &amp;uuml;st&amp;uuml;ne basa basa s&amp;ouml;yl&amp;uuml;yorum:&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Filistin halkının yanında olmanın yolu;&amp;nbsp;Filistin&amp;rsquo;i tanımak kadar İsrail&amp;rsquo;i tanımaktan ge&amp;ccedil;er.&lt;a name=&quot;_Toc211334548&quot;&gt;&lt;/a&gt;&lt;a name=&quot;_Toc211406306&quot;&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;İ&amp;Ccedil;İ SAMAN DOLU BARIŞ G&amp;Uuml;VERCİNİ TRUMP&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Değerli Arkadaşlar,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;100 yılı aşkın bir zamandır nerede kan ve g&amp;ouml;zyaşı varsa orada ABD parmağının olduğunu hepimiz biliyoruz. Hal b&amp;ouml;yleyken; k&amp;uuml;resel sermayenin ve s&amp;ouml;m&amp;uuml;r&amp;uuml;n&amp;uuml;n&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;en besili taşeronu Trump,&amp;ldquo;barış g&amp;uuml;vercini&amp;rdquo; olarak pazarlanıyor. B&amp;uuml;t&amp;uuml;n d&amp;uuml;nyaya karşı korkun&amp;ccedil; bir tiyatro sahnelendi ve sahneleniyor.&amp;nbsp;Barış G&amp;uuml;vercini dedikleri Trump, Netanyahu&amp;rsquo;ya;&amp;nbsp;&amp;ldquo;Bibi yani Netanyahu beni s&amp;uuml;rekli arayıp benden şu silahı, bu silahı isterdi... istediği silahların kimisinin ismini bile bilmiyordum... ama o silahları yaptım ve g&amp;ouml;nderdim... en iyileriydi... o da bunları iyi kullandı... gayet iyi kullandı... İsrail &amp;ccedil;ok g&amp;uuml;&amp;ccedil;l&amp;uuml; hale geldi...&amp;rdquo;&amp;nbsp;diyor&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Şimdi bunu bir barış el&amp;ccedil;isi gibi g&amp;ouml;stermek; bu d&amp;uuml;nyanın şahit olup olabileceği en b&amp;uuml;y&amp;uuml;k sahtekarlıklardan biridir. Sahneye o kadar &amp;ouml;zenmişler ki; İsrail ziyaretinde Netanyahu, Trump&amp;rsquo;a altından bir g&amp;uuml;vercin heykel hediye etti.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Netanyahu&amp;rsquo;nun Trump&amp;rsquo;a hediye ettiği barış g&amp;uuml;vercininin gagası var, kanatları var.&amp;nbsp;Ancak! Ruhu yok! Bu g&amp;uuml;vercin u&amp;ccedil;amaz, bu g&amp;uuml;vercin kimseye barış getiremez!&amp;nbsp;Trump; i&amp;ccedil;i saman dolu bir barış g&amp;uuml;vercinidir.&lt;a name=&quot;_Toc211334549&quot;&gt;&lt;/a&gt;&lt;a name=&quot;_Toc211406307&quot;&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;KABUL ETMİYORUZ VE KARŞIYIZ&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;T&amp;uuml;rkiye B&amp;uuml;y&amp;uuml;k Millet Meclisi&amp;rsquo;nden bir kez daha iktidara sesleniyoruz: İbrahim Anlaşmalarını b&amp;ouml;lgeye dikte ettirme anlamına gelen hi&amp;ccedil;bir adımı kabul etmeyin.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;ldquo;B&amp;ouml;lge yakında harika bir yer olacak&amp;rdquo; denilerek, b&amp;ouml;lgenin yeni bir cehenneme d&amp;ouml;n&amp;uuml;şt&amp;uuml;r&amp;uuml;lmesine m&amp;uuml;saade etmeyin. Gazzelilerin, &amp;ldquo;G&amp;ouml;n&amp;uuml;ll&amp;uuml; Yer Değiştirme Programı&amp;rdquo; adı altında,&amp;nbsp;&lt;span style=&quot;color:black&quot;&gt;zorla tehcir edilme planlarına engel olun.&amp;nbsp;&lt;/span&gt;Sakın iktidarınızı devam ettirebilmek i&amp;ccedil;in b&amp;ouml;yle bir planın i&amp;ccedil;erisinde yer almayın!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;Ccedil;&amp;uuml;nk&amp;uuml;: ABD&amp;rsquo;nin ve İsrail&amp;rsquo;in i&amp;ccedil;inde bulunduğu hi&amp;ccedil;bir anlaşmadan, barış &amp;ccedil;ıkmaz! ABD&amp;rsquo;nin planından bu coğrafyaya hayır gelmez!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Biz, Trump&amp;rsquo;ın &amp;ouml;nc&amp;uuml;l&amp;uuml;ğ&amp;uuml;nde y&amp;uuml;r&amp;uuml;t&amp;uuml;len ve b&amp;ouml;lgeye &amp;ldquo;yeni bir dayatma girişimi&amp;rdquo; olarak g&amp;ouml;rd&amp;uuml;ğ&amp;uuml;m&amp;uuml;z bu planlara karşı &amp;ccedil;ıkmayı; tarih&amp;icirc; bir sorumluluk vicdan&amp;icirc; ve insan&amp;icirc; bir vazife olarak g&amp;ouml;r&amp;uuml;yoruz.&lt;a name=&quot;_Toc211334550&quot;&gt;&lt;/a&gt;&lt;a name=&quot;_Toc211406308&quot;&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;AFGANİSTAN-PAKİSTAN GERİLİMİ&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Gazze&amp;rsquo;deki insani trajedi g&amp;uuml;ndemin odağındayken, Afganistan-Pakistan sınır hattında yaşanan son gelişmeler de dikkatle izlenmelidir. Bilinmelidir ki; bu kavganın kazananı kimse olmayacaktır. Kazanan b&amp;ouml;lge &amp;uuml;lkelerinin istikrarsızlığından faydalanan k&amp;uuml;resel g&amp;uuml;&amp;ccedil;ler olacaktır. Başta T&amp;uuml;rkiye ve b&amp;ouml;lge &amp;uuml;lkeleri arabulucu olmalı ve kardeş kanının akmasına mani olunmalıdır.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Her iki &amp;uuml;lkeyi de diplomatik a&amp;ccedil;ıdan &amp;ccedil;&amp;ouml;z&amp;uuml;m &amp;uuml;retmeye, ter&amp;ouml;r &amp;ouml;rg&amp;uuml;tlerine karşı ortak m&amp;uuml;cadeleye, sağduyuya ve diyaloğa davet ediyoruz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;19.&lt;/span&gt;&lt;span style=&quot;font-family:&amp;quot;Segoe UI Symbol&amp;quot;,sans-serif&quot;&gt;⁠&lt;/span&gt;&amp;nbsp;&lt;span style=&quot;font-family:&amp;quot;Segoe UI Symbol&amp;quot;,sans-serif&quot;&gt;⁠&lt;/span&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Y&amp;uuml;zyılda s&amp;ouml;m&amp;uuml;rge haline getirdikleri İslam topraklarında kendilerinden sonra &amp;ccedil;atışma, kargaşa ve savaşlar devam etsin diye tuzaklar kuranların hedefi bu b&amp;ouml;lgelerin hi&amp;ccedil;bir zaman istikrar ve barışa ulaşmamasıdır.&amp;nbsp;&lt;a name=&quot;_Toc211334551&quot;&gt;&lt;/a&gt;&lt;a name=&quot;_Toc211406309&quot;&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;ldquo;İŞTE BENİM ANAYASAM&amp;rdquo;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Değerli arkadaşlar,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;T&amp;uuml;m bu gerilimler, coğrafyamızın karşı karşıya olduğu daha b&amp;uuml;y&amp;uuml;k bir s&amp;uuml;recin par&amp;ccedil;alarıdır. B&amp;ouml;ylesi bir d&amp;ouml;nemde sadece dış politikamızda değil, kendi i&amp;ccedil; d&amp;uuml;zenimizde de adaletin, hakkaniyetin ve ortak iradenin h&amp;acirc;kim olması hayati &amp;ouml;nem taşımaktadır. &amp;ldquo;Yeni Anayasa&amp;rdquo; yine g&amp;uuml;ndemde. &amp;Ccedil;ok net şu soruları sormak istiyoruz. Siz bu &amp;ldquo;Yeni Anayasayı&amp;rdquo; ni&amp;ccedil;in istiyorsunuz? Demokratik bir T&amp;uuml;rkiye i&amp;ccedil;in mi, yoksa kendi Otokratik rejiminize zemin hazırlamak i&amp;ccedil;in mi?&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Biz; sivil, dili ve i&amp;ccedil;eriğiyle bug&amp;uuml;n&amp;uuml; ve yarını kucaklayan, -en &amp;ouml;nemlisi- 86 milyonun tamamının &amp;ldquo;İşte benim anayasam&amp;rdquo; diyerek sahipleneceği, baş tacı edeceği bir Anayasanın en b&amp;uuml;y&amp;uuml;k destek&amp;ccedil;isi oluruz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Ancak, &amp;ouml;nce mevcut anayasaya uyulmasını bunun neticesinde ortaya &amp;ccedil;ıkan eksiklerin tartışılmasını bekleriz. Eski Anayasa, hukuka uymamak i&amp;ccedil;in bir bahane, yeni Anayasa da i&amp;ccedil; politikayı dizayn edecek bir malzeme olmamalıdır!&lt;/span&gt;&lt;a name=&quot;_Toc211334552&quot;&gt;&lt;/a&gt;&lt;a name=&quot;_Toc211406310&quot;&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;MİLLİ DAYANIŞMA, KARDEŞLİK VE DEMOKRASİ KAYYIMI&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bu yeni anayasa ve demokratikleşme konusunda epey bir a&amp;ccedil;ıklama yapan ve Cumhurbaşkanı danışmanı olduğunu bildiğimiz bir zat, her pazar g&amp;uuml;n&amp;uuml; Meclis&amp;#39;e ve Meclis&amp;#39;te kurulan Milli Dayanışma, Kardeşlik ve Demokrasi Komisyonu&amp;#39;na rol bi&amp;ccedil;ip y&amp;ouml;n vermeye kalkıyor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bu arkadaş komisyonun başına atanmış bir &amp;ldquo;kayyum&amp;rdquo; gibi davranıyor. S&amp;uuml;re&amp;ccedil;te; ne konuşulacak, ne konuşulmayacak, bununla ilgili kendini yetki sahibi sanıyor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Arkadaşlar, şunu bir netleştirelim: Kimse, meclis iradesinin &amp;uuml;zerinde değildir. Kimse meclise y&amp;ouml;n veremez, &amp;ccedil;er&amp;ccedil;eve &amp;ccedil;izemez, ne yapacağını s&amp;ouml;yleyemez. Yeni Anayasa&amp;rsquo;dan bahsedenler, &amp;ouml;nce bu kayyum zihniyetinde bir &amp;ccedil;ıksınlar!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bakın biz en başından beri şunu s&amp;ouml;yledik: İhtiyacımız olanı; &amp;ldquo;Ter&amp;ouml;rs&amp;uuml;z T&amp;uuml;rkiye&amp;rdquo; tabiri ifade etmeye yetmiyor, bizim ihtiyacımız olan &amp;ldquo;Yaşanabilir T&amp;uuml;rkiye&amp;rdquo; ifadesidir dedik. Toplumsal barış ve huzuru &amp;ldquo;bir &amp;ouml;rg&amp;uuml;t&amp;uuml;n silah bırakmasına&amp;rdquo; indirgemenin&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;ccedil;ıkmaz yol olduğunu s&amp;ouml;yledik.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Ancak g&amp;ouml;rd&amp;uuml;ğ&amp;uuml;m&amp;uuml;z o ki; kendini kayyum sanan arkadaş toplumun farklı kesimlerinin hak ve &amp;ouml;zg&amp;uuml;rl&amp;uuml;klere dair taleplerini dile getirmesini istemiyor. Komisyonun bu konulara giremeyeceğini iddia ediyor. İşte tam da bu anlayış, bu &amp;uuml;lkeyi yaşanabilir olmaktan &amp;ccedil;ıkarıyor.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc211334553&quot;&gt;&lt;/a&gt;&lt;a name=&quot;_Toc211406311&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;KALICI VE KAPSAYICI BİR &amp;Ccedil;&amp;Ouml;Z&amp;Uuml;M&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Kalıcı ve kapsayıcı bir &amp;ccedil;&amp;ouml;z&amp;uuml;m: Tutuklu Başkanlardan, Kayyım atanmış belediyelere; tutuklu gazetecilerden, Adalet arayışında olan KHK&amp;rsquo;lılara; ev kirasını &amp;ouml;deyemeyen asgari &amp;uuml;cretlilerden, atama bekleyen &amp;ouml;ğretmenlere; AVM&amp;#39;lerin kuşatması altında can &amp;ccedil;ekişen esnaftan, her sezonu daha b&amp;uuml;y&amp;uuml;k zararla kapatan &amp;ccedil;ift&amp;ccedil;ilere; engelsiz şehirler isteyen engelli vatandaşlarımızdan, şiddet g&amp;ouml;rme endişesi taşıyan kadınlara; adalet arayışında olan herkesi s&amp;uuml;recin dışında değil, tam merkezinde konumlandırmakla&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;m&amp;uuml;mk&amp;uuml;nd&amp;uuml;r.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;Ouml;rg&amp;uuml;t&amp;uuml;n silah bırakması konusunda, kimsenin itirazı olmaz, olamaz da! Bununla birlikte hi&amp;ccedil; kimse bizden keyfiliğin, kayırmacılığın ve hukuksuzluğun dayatılmasına da rıza g&amp;ouml;stermemizi beklemesin.&amp;nbsp;&lt;a name=&quot;_Toc211334554&quot;&gt;&lt;/a&gt;&lt;a name=&quot;_Toc211406312&quot;&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;strong&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;ESAS KONUŞULMASI GEREKEN&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Değerli arkadaşlar;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;T&amp;uuml;rkiye&amp;rsquo;de; sosyal medya kahramanlarının, televizyon yorumcularının &amp;ldquo;g&amp;uuml;ndem budur&amp;rdquo; dediği şeylerin dışında bir ger&amp;ccedil;eklik var. Bizler i&amp;ccedil;in ger&amp;ccedil;eklik; T&amp;uuml;m kaynaklarımızı yok eden ekonomik buhrandır! Vergi, Enflasyon ve Faiz ile y&amp;ouml;netilmeye &amp;ccedil;alışılan ekonomidir.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;a name=&quot;_Toc211334555&quot;&gt;&lt;/a&gt;&lt;a name=&quot;_Toc211406313&quot;&gt;&lt;/a&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;h1 style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:12pt&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#c00000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;VERGİ: AZ KAZANANDAN &amp;Ccedil;OK, &amp;Ccedil;OK KAZANANDAN AZ&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/h1&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bakınız, Bu milletten, bu yıl sonuna kadar 12 trilyon 651 milyar vergi toplanacak.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bu verginin de %85&amp;rsquo;ini dar gelirliler &amp;ouml;deyecek.&amp;nbsp;&lt;span style=&quot;color:black&quot;&gt;Ge&amp;ccedil;tiğimiz g&amp;uuml;nlerde Hazine ve maliye bakanımız vergi konusunda &amp;ccedil;ıktı;&amp;nbsp;&amp;ldquo;az kazanandan az, &amp;ccedil;ok kazanandan &amp;ccedil;ok alacağız&amp;rdquo;&amp;nbsp;dedi.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&lt;span style=&quot;color:black&quot;&gt;&amp;Uuml;z&amp;uuml;lerek s&amp;ouml;yl&amp;uuml;yorum; bu a&amp;ccedil;ıklama, bug&amp;uuml;ne kadar az kazanandan &amp;ccedil;ok, &amp;ccedil;ok kazanandan az vergi alındığının itirafıdır.&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Bakınız ge&amp;ccedil;tiğimiz hafta sonu, evini kiraya verenlere %20 stopaj uygulanacağına dair bir d&amp;uuml;zenleme g&amp;uuml;ndeme geldi. Sonra Hazine ve Maliye bakanlığı hemen yalanladı. Biz aynı senaryoyu, yurt dışı &amp;ccedil;ıkış harcında da yaşamıştık.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Sonra birden har&amp;ccedil;ların y&amp;uuml;kseldiğini g&amp;ouml;rd&amp;uuml;k. Umarız, bu konuda da bir benzeri yaşanmaz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&amp;nbsp;&lt;/p&gt;

