&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;Ekonomi bakanı defalarca değişti, Merkez Bankası Başkanıda defalarca değişti,&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;ekonomi politikasıda defalarca değişti, ama&amp;nbsp;&lt;strong&gt;&amp;ldquo;T&amp;uuml;rkiye&amp;rsquo;nin enflasyon ger&amp;ccedil;eği&amp;rdquo;&lt;/strong&gt;&amp;nbsp;hi&amp;ccedil; değişmedi! Bunu bilerek, hissederek s&amp;ouml;yl&amp;uuml;yorum!&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

&lt;p style=&quot;text-align:justify&quot;&gt;&lt;span style=&quot;font-size:medium&quot;&gt;&lt;span style=&quot;font-family:Arial,sans-serif&quot;&gt;&lt;span style=&quot;color:#000000&quot;&gt;&lt;span style=&quot;font-family:Aptos,sans-serif&quot;&gt;&amp;Ccedil;&amp;uuml;nk&amp;uuml; biz enflasyonu; Mehmet Şimşeğin havalı tweetlerinde, T&amp;Uuml;İK&amp;rsquo;in makyajlı rakamlarında değil; milletin enflasyonu acı acı hissettiği&amp;nbsp;&amp;ccedil;arşıda, pazarda, kasapta&amp;nbsp;g&amp;ouml;r&amp;uuml;yoruz.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;

